"仓库里是你所有的物资、图纸和宝物，有多少显示多少。鼠标悬浮可以查看详情，点击画面其它地方就能关闭。": "W magazynie są wszystkie twoje zapasy, plany i relikwie — tyle, ile ich masz. Najedź, by zobaczyć szczegóły; kliknij gdziekolwiek indziej, by zamknąć.",
