"任何房间": "Dowolne pomieszczenie",
"任何房间：主基地耐久 +{0}%。契合「防御」：守城时 {1} 名陶土守卫加入战斗。": "Dowolne pomieszczenie: wytrzymałość Twierdzy +{0}%. Pasuje do „Obrona”: w obronie dołączają gliniani strażnicy ({1}).",
"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Dowolne pomieszczenie: limit relikwii na wyprawie +{0}. Pasuje do „Obrona”: broń: obrażenia +{1}%, trafienia ranią obszarowo i spowalniają; inne: dodatkowi strażnicy ({2}).",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Dowolne pomieszczenie: zapasy z wypraw +{0}%. Pasuje do „Fortuna”: zapasy jeszcze +{1}%, początkowy mnożnik punktów w każdej bitwie +{2}.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Dowolne pomieszczenie: pole widzenia na wyprawie +{0}, początkowy mnożnik punktów +{1}. Pasuje do „Fortuna / Specjalne”: mapa wyprawy od początku odkryta, mnożnik punktów jeszcze +{2}.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Dowolne pomieszczenie: atak jednostek na wyprawie +{0}%. Pasuje do „Trening”: PD przywódcy z wypraw +{1}%.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Dowolne pomieszczenie: zdrowie jednostek na wyprawie +{0}%. Pasuje do „Lecznictwo”: leczenie w szpitalu +{1}%, przywódca odzyskuje dziennie dodatkowe {2}%.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Dowolne pomieszczenie: szansa na plany +{0}%. Pasuje do „Sci-fi”: baza: Odłamki dusz +{1} dziennie.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Dowolne pomieszczenie: szansa na plany +{0}%. Pasuje do „Kowalstwo”: {1}% szans na dodatkową relikwię przy wykuwaniu.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Dowolne pomieszczenie: baza: Odłamki dusz +{0} dziennie. Pasuje do „Magia”: dodatkowo +{1} dziennie.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Dowolne pomieszczenie: baza: Zapasy +{0} dziennie. Pasuje do „Logistyka”: własny efekt tego pomieszczenia ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Dowolne pomieszczenie: baza: Zapasy +{0} dziennie, przywódca zyskuje {1} PD dziennie. Pasuje do „Logistyka / Natura”: własny efekt tego pomieszczenia ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Dowolne pomieszczenie: koszt wykuwania relikwii -{0}%. Pasuje do „Kowalstwo / Broń”: kowalstwo: {1}% szans na jakość +{2}; broń: obrażenia +{3}%.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Dowolne pomieszczenie: czas budowy o połowę krótszy, po ukończeniu zwrot {0}% zapasów. Pasuje do „Cud”: zwrot rośnie do {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Dowolne pomieszczenie: obrażenia wszystkich wież obronnych +{0}%. Pasuje do „Broń”: zasięg +{1}, szybkość ataku +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Dowolne pomieszczenie: koszt kopania -{0}%. Pasuje do „Specjalne”: każda budowa trwa o {1} d. krócej.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Dowolne pomieszczenie: początkowy mnożnik punktów w każdej bitwie +{0}. Pasuje do „Kowalstwo”: wykuwane relikwie zawsze mają jakość +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Dowolne pomieszczenie: odnowienie umiejętności przywódcy krótsze o {0} et. Pasuje do „Fortuna”: na start wyprawy dodatkowe przedmioty wsparcia: {1} (efekt co najmniej „Epicki”).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Dowolne pomieszczenie: atak przywódcy +{0}%. Pasuje do „Broń”: obrażenia +{1}%, każdy atak wyzwala łańcuch błyskawic (celów: {2}).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Dowolne pomieszczenie: przywódca odzyskuje {0}% zdrowia dziennie (bez szpitala). Pasuje do „Lecznictwo / Woda”: leczenie w szpitalu +{1}%; zasięg broni wodnej +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Dowolne pomieszczenie: przywódca zyskuje {0} PD dziennie. Pasuje do „Produkcja”: własna produkcja tego pomieszczenia ×{1}.",
"任何房间：领袖每天获得 {0} 经验。契合「训练」：领袖出征得到的经验 +{1}%。": "Dowolne pomieszczenie: przywódca zyskuje {0} PD dziennie. Pasuje do „Trening”: PD przywódcy z wypraw +{1}%.",
"任何房间：领袖生命 +{0}%。契合「训练」：领袖攻击 +{1}%。": "Dowolne pomieszczenie: zdrowie przywódcy +{0}%. Pasuje do „Trening”: atak przywódcy +{1}%.",
