"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "Przed tobą „Cmentarz”: mgła jest najgęstsza na cmentarzu za miastem, a nowych grobów z każdą nocą przybywa.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "Przed tobą „Hala montażowa”: ostatnia rzecz, jaką zbudowała fabryka, zmieściła w sobie wszystkich jej ludzi.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Przed tobą „Sala operacyjna”: dyrektor mówi, że operacja się udała — pacjent po prostu jeszcze się nie obudził.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Przed tobą „Dno morza”: pod portem jest jeszcze jedno miasto, a jego brama to paszcza.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Przed tobą „Drzewo Wiedzy”: stare drzewo pamięta wszystko, co wydarzyło się w lesie. Nie chce pamiętać niczego więcej.",
